<?php
session_start();require_once '../conexao.php';require_once '../includes/flash.php';
if($_SERVER['REQUEST_METHOD']==='POST'){$email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL);if($email){$s=$pdo->prepare('SELECT id,nome FROM pacientes WHERE email=? AND ativo=1');$s->execute([$email]);if($u=$s->fetch()){$token=bin2hex(random_bytes(32));$hash=hash('sha256',$token);$exp=date('Y-m-d H:i:s',time()+3600);$pdo->prepare('DELETE FROM redefinicoes_senha WHERE paciente_id=?')->execute([$u['id']]);$pdo->prepare('INSERT INTO redefinicoes_senha(paciente_id,token_hash,expira_em) VALUES(?,?,?)')->execute([$u['id'],$hash,$exp]);$scheme=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'https':'http';$base=rtrim(dirname($_SERVER['PHP_SELF']),'/\\');$link=$scheme.'://'.$_SERVER['HTTP_HOST'].$base.'/redefinir-senha.php?token='.urlencode($token);$assunto='Redefinição de senha - Espaço Aura';$msg="Olá {$u['nome']},\n\nUse o link abaixo para redefinir sua senha. Ele expira em 1 hora:\n$link\n\nSe você não solicitou, ignore esta mensagem.";$headers="From: Espaço Aura <nao-responda@espacoaura.com.br>\r\nContent-Type: text/plain; charset=UTF-8";@mail($email,$assunto,$msg,$headers);if(defined('AURA_DEV')&&AURA_DEV){file_put_contents(__DIR__.'/../storage/reset-mails.log',date('c')." | $email | $link\n",FILE_APPEND);}}}flash('success','Se o e-mail estiver cadastrado, enviaremos um link de redefinição válido por 1 hora.');header('Location: esqueci-senha.php');exit;}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Recuperar senha | Espaço Aura</title><link rel="icon" type="image/png" sizes="512x512" href="../img/favicon-aura.png"><link rel="shortcut icon" href="../img/favicon.ico"><link rel="stylesheet" href="../css/style.css"></head><body><main class="form-page"><div class="form-container"><p class="eyebrow">ÁREA DO PACIENTE</p><h1>Esqueceu sua senha?</h1><p class="muted">Informe seu e-mail para receber o link de redefinição.</p><?php mostrarFlash();?><form method="post" class="form-card"><label>E-mail<input type="email" name="email" required></label><button class="btn btn-full">Enviar link</button><p style="text-align:center"><a href="login.php">Voltar ao login</a></p></form></div></main><script src="../js/app.js"></script></body></html>